/* Tres diapositivas por equipo. Las autorías y la evaluación solo llegan a la sesión docente. */
(()=>{'use strict';const root=document.getElementById('market'),q=new URLSearchParams(location.search),teacher=q.get('docente')==='1',portfolio=q.get('portafolio')==='1',config=window.AulaSupabaseConfig;
if(portfolio)document.title='Mi portafolio';
const S={snap:null,slide:portfolio?-1:0,ods:null,odsDraft:null,mode:portfolio||q.get('modo')==='presentacion'?'presentacion':'edit',actor:'',pending:{},authors:{},busy:false,notice:'',error:false,application:false,rubric:null,responseDraft:null};let client;
const E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isFive=()=>S.snap?.team?.grade===5;
const surveyOnly=()=>[5,6].includes(S.snap?.team?.grade);
const isSix=()=>S.snap?.team?.grade===6;
const gradeName=()=>isFive()?'Quinto':isSix()?'Sexto':'Séptimo';
const countName=()=>isFive()?'cinco':isSix()?'seis':'ocho';
const questionCount=()=>isFive()?5:isSix()?6:8;
const marketSlides=()=>[0,...(surveyOnly()?[]:[1]),2,...(content().technique==='encuesta'?[20]:[]),...((content().technique==='encuesta'||content().technique==='entrevista')?resultPages().map((_,i)=>30+i):[])];
const hasMarket=()=>!!S.snap?.work?.version&&Object.entries(S.snap.work.content||{}).some(([k,v])=>k!=='technique'&&String(v||'').trim());
const hasODS=()=>!!S.ods?.work?.savedAt&&!!S.ods?.publication&&((S.ods.work.content?.ods||[]).some(Boolean)||(S.ods.work.content?.reasons||[]).some(Boolean)||!!S.ods.work.content?.indicator);
const coverPilot=()=>portfolio&&S.snap?.team?.grade===6&&S.snap?.team?.parallel==='C'&&S.snap?.team?.group===1;
const slides=()=>portfolio?[...(coverPilot()?[-2,-3]:[]),...(hasODS()?[-1]:[]),...(coverPilot()?[0,...(hasMarket()?marketSlides().filter(i=>i>=30):[])]:hasMarket()?marketSlides():[])]:marketSlides();
const slideLabel=i=>i===-3?'Problema':i===-2?'Portada':i===-1?(coverPilot()?'ODS vinculadas al proyecto':'ODS vinculados al proyecto'):i===0?'Público objetivo':i===1?'Necesidad y usuarios':i===2?'Investigación de mercado':i===20?'Encuesta · continuación':resultPages()[i-30]?.analysis?'Nuestro análisis':'Resultados';
const questionPurposes=()=>isFive()?['Conocer al cliente','Descubrir su necesidad','Conocer su situación actual','Conocer sus preferencias','Investigar los precios']:isSix()?['Conocer al cliente','Conocer su situación actual','Descubrir el problema','Descubrir sus necesidades','Conocer sus preferencias','Investigar los precios']:['Conocer al cliente','Conocer su situación actual','Descubrir el problema','Descubrir sus necesidades','Conocer sus preferencias','Conocer el modo de uso','Investigar los precios','Valorar el interés'];
const purposes=['Conocer al cliente','Descubrir necesidades','Conocer sus preferencias','Investigar los precios'];
const fieldLabels={need:'Necesidad que queremos conocer',user:'Quién utilizaría la solución',buyer:'Quién podría comprarla',technique:'Técnica principal',application:'Aplicación del instrumento'};
const content=()=>({...S.snap?.work?.content,...S.pending,...(surveyOnly()?{technique:'encuesta'}:{})}),editable=()=>!teacher&&S.mode==='edit'&&S.snap?.publication?.state==='available',enabled=()=>editable()&&!!S.actor&&!S.busy;
const button=(label,action,primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':''}" data-market="${action}" ${extra}>${label}</button>`;
async function rpc(name,args={}){if(name.startsWith('aula_market_')){name=name.replace('aula_market_','aula_market_v2_');if(name.endsWith('snapshot'))args={...args,p_grade:S.snap?.team?.grade||+q.get('grado')||7};}const {data,error}=await client.rpc(name,args);if(error)throw Error(error.message||'No se pudo guardar.');return data;}
function note(message,error=false){S.notice=message;S.error=error;}
function actorName(id){return S.snap?.members?.find(m=>m.id===id)?.name||'';}
function author(key,present){if(!teacher||present)return '';const c=S.snap.contributions?.find(x=>x.field_key===key);return `<span class="contributor">Aporte de: ${c?E(c.name):'Sin registrar'}</span>`;}
function field(key,label,placeholder='',present=false,input=false){const value=content()[key]||'';if(present||teacher)return `<div class="market-field"><span>${E(label)}</span><p class="presentation-text">${E(value||'Por completar')}</p>${author(key,present)}</div>`;return `<label class="market-field">${E(label)}${input?`<input data-key="${key}" value="${E(value)}" placeholder="${E(placeholder)}" maxlength="${key.includes('audience')?180:300}" ${enabled()?'':'disabled'}>`:`<textarea data-key="${key}" rows="2" maxlength="${key.startsWith('q')?500:2000}" placeholder="${E(placeholder)}" ${enabled()?'':'disabled'}>${E(value)}</textarea>`}</label>`;}
function projectContext(){const t=S.snap.team;return `${t.name||'Equipo '+t.group} · ${gradeName()} ${t.parallel} · ${t.title}`;}
function audience(i,present){const d=content(),image=d[`audience${i}_image`],safe=typeof image==='string'&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(image),nameKey=`audience${i}_name`;return `<article class="audience-card"><div class="audience-picture">${safe?`<img src="${image}" alt="${E(d[nameKey]||'Público '+(i+1))}">`:`<span aria-hidden="true">♙</span>`}</div>${editable()&&!present?`<div class="audience-tools"><label class="upload-label">${image?'Cambiar imagen':'Subir imagen'}<input type="file" accept="image/*" data-image="${i}" aria-label="Subir imagen del público ${i+1}" ${enabled()?'':'disabled'}></label>${image?button('Quitar','remove-image',false,`data-index="${i}" ${enabled()?'':'disabled'}`):''}</div>`:''}${field(nameKey,`Público ${i+1}`, '¿Quién es este público?',present,true)}${author(`audience${i}_image`,present)}</article>`;}
function slide(index,present=false){if(index===0&&coverPilot())return pilotAudienceView(present);if(index===-3)return window.PortfolioProblem.view(!present&&S.mode==='edit');if(index===-2)return window.PortfolioCover.view(!present&&S.mode==='edit');if(index===-1)return odsSlide(present);if(index>=30)return resultsSlide(index,present);const pageIndex=index;if(index===20)index=2;const d=content(),t=S.snap.team,names=['Mi público objetivo','Comprendemos a nuestro público','Investigación de mercado'];let body='';
 if(index===0){const active=[0,1,2,3].filter(i=>d[`audience${i}_name`]||d[`audience${i}_image`]);const slots=present?active:[0,1,2,3];body=`<div class="wheel"><svg class="spokes" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true"><path d="M240 120L500 250L760 120M240 380L500 250L760 380" stroke="#e9c0d2" stroke-width="3" fill="none"/></svg><div class="wheel-hub"><strong>Público<br>objetivo</strong><span>Personas a quienes queremos ayudar</span></div>${slots.length?slots.map(i=>audience(i,present)).join(''):'<p class="slide-tip">Público por completar.</p>'}</div>${present?'':`<p class="slide-tip">Completen de uno a cuatro públicos. Suban una imagen representativa y escriban debajo quién es. Los espacios vacíos no aparecerán en su presentación.</p>`}`;}
 if(index===1){body=`<div class="public-cards">${[['need','¿Qué necesidad queremos conocer?','¿Qué dificultad debemos investigar antes de crear?','◉'],['user','¿Quién utilizaría nuestra solución?','Indiquen quién la usaría en su vida diaria.','♙'],['buyer','¿Quién podría comprarla?','Puede ser otra persona o institución. Si no hay compra, expliquen «No aplica».','◇']].map(([k,label,hint,icon])=>`<article class="public-card"><div class="symbol" aria-hidden="true">${icon}</div>${field(k,label,hint,present)}</article>`).join('')}</div>`;}
 if(index===2){const technique=surveyOnly()?'encuesta':d.technique,observation=technique==='observacion';body=`${present||teacher||surveyOnly()?`<p><b>Técnica principal:</b> ${E(({encuesta:'Encuesta',entrevista:'Entrevista',observacion:'Observación'})[technique]||'Por elegir')}</p>${author('technique',present)}`:`<div class="techniques" role="group" aria-label="Técnica principal">${[['encuesta','☑ Encuesta'],['entrevista','◉ Entrevista'],['observacion','◌ Observación']].map(([value,label])=>`<label><input type="radio" name="technique" value="${value}" data-technique ${technique===value?'checked':''} ${enabled()?'':'disabled'}>${label}</label>`).join('')}</div><div class="market-actions">${button('Usar inicios y opciones sugeridos','suggestions',false,enabled()?'':'disabled')}<span class="slide-tip">Sugerencias editables para su proyecto; no son respuestas de clientes.</span></div>`}
 ${!present&&!teacher?button('Usar ejemplos de mi proyecto','suggestions',false,enabled()?'':'disabled'):''}<div class="questions-grid">${questionPurposes().map((p,i)=>({p,i})).slice(pageIndex===20?4:0,pageIndex===20?questionCount():4).map(({p,i})=>`<article class="question-card"><h3>${i+1}. ${p}</h3>${questionChoices(i,present)}${field(`q${i}_text`,observation?'Aspecto o pregunta de observación':'Pregunta',suggestions()[`q${i}_text`],present)}<div class="options">${['a','b','c'].map((letter,j)=>present||teacher?`<p class="presentation-option">○ ${E(d[`q${i}_${letter}`]||'Opción por completar')}</p>${author(`q${i}_${letter}`,present)}`:`<label class="option market-field"><b>${j+1}</b><input aria-label="Pregunta ${i+1}, opción ${j+1}" data-key="q${i}_${letter}" value="${E(d[`q${i}_${letter}`]||'')}" placeholder="${E(suggestions()[`q${i}_${letter}`])}" maxlength="120" ${enabled()?'':'disabled'}></label>`).join('')}</div>${technique==='entrevista'?`<div class="followup">${field(`q${i}_why`,'Seguimiento','¿Por qué? / ¿Puedes contarme un ejemplo?',present,true)}</div>`:''}</article>`).join('')}</div>${!present?`<p class="slide-tip">${observation?'Registren hechos visibles. Para precios observen una lista, menú, catálogo o costo documentado; no deduzcan cuánto pagaría una persona solo mirándola.':'Antes de aplicar, revisen que las opciones sean claras y diferentes. Pueden incluir «No lo sé» o «No aplica» cuando corresponda.'}</p>`:''}`;}
 if(index===2&&d.technique==='entrevista')body=techniquePicker(present)+interviewView(present);
 if(index===2&&d.technique==='observacion')body=techniquePicker(present)+empathyView(present);
 return `<section class="market-deck"><header class="slide-head"><div><p class="eyebrow">INVESTIGACIÓN DE MERCADO Y PÚBLICO OBJETIVO</p><h2>${pageIndex===20?'Encuesta · preguntas 5 a '+questionCount():names[index]}</h2><p class="project-line">${E(projectContext())}</p></div><span class="tag">0${slides().indexOf(pageIndex)+1}</span></header>${body}<footer class="slide-footer"><span>Eight Academy · Emprendimiento</span><span>${slides().indexOf(pageIndex)+1} / ${slides().length}</span></footer></section>`;
}
function seventhSuggestions(){const t=S.snap?.team||{},title=(t.title||'nuestro proyecto').split(':')[0],full=(t.title+' '+t.problem+' '+t.solution).toLowerCase();let context='la situación que aborda '+title,features=['Facilidad de uso','Información clara','Ahorro de tiempo'];
 if(/cafeter|menú/.test(full)){context='elegir y pedir alimentos en la cafetería escolar';features=['Precio','Sabor','Ingredientes'];}
 else if(/pitch/.test(full)){context='preparar una presentación de emprendimiento';features=['Practicar preguntas','Controlar el tiempo','Recibir comentarios'];}
 else if(/feria|stands/.test(full)){context='conocer proyectos en una feria de emprendimientos';features=['Ver el prototipo','Escuchar el pitch','Hacer preguntas'];}
 else if(/cotiz|servicios/.test(full)){context='calcular el precio de un servicio estudiantil';features=['Cálculo claro','Comparar costos','Ahorrar tiempo'];}
 else if(/carga acad|planificador|tareas/.test(full)){context='organizar tareas de la semana';features=['Ver pendientes','Recordatorios','Distribuir el tiempo'];}
 else if(/cosecha/.test(full)){context='registrar el destino de una cosecha';features=['Cantidades claras','Historial de destinos','Porcentaje aprovechado'];}
 else if(/recorrido|ecotour/.test(full)){context='recorrer la Zoobotánica';features=['Mapa sencillo','Información de especies','Retos del recorrido'];}
 else if(/hábitat|habitat|microclim|especies|gemelo/.test(full)){context='consultar y registrar los cuidados de la Zoobotánica';features=['Alertas comprensibles','Registro de cuidados','Datos de la especie'];}
 else if(/energ/.test(full)){context='usar y cuidar la energía en la escuela';features=['Ahorro de energía','Facilidad de uso','Información del consumo'];}
 const d={q0_text:`¿Con qué frecuencia necesitas ${context}?`,q0_a:'Frecuentemente',q0_b:'A veces',q0_c:'Nunca o no aplica',q1_text:`¿Qué te resulta más difícil al ${context}?`,q1_a:'Encontrar información',q1_b:'Organizar lo que debo hacer',q1_c:'Otra dificultad / no aplica',q2_text:`¿Qué valorarías más en una solución como ${title}?`,q2_a:features[0],q2_b:features[1],q2_c:features[2],q3_text:`¿Qué sabes del costo actual de ${context}?`,q3_a:'Actualmente no tiene costo directo',q3_b:'Tiene un costo que puedo indicar',q3_c:'No lo sé / no aplica'};
 if(content().technique==='observacion')Object.assign(d,{q0_text:`¿Cómo se realiza actualmente la actividad de ${context}?`,q0_a:'Con ayuda de otra persona',q0_b:'De forma autónoma',q0_c:'No se pudo observar',q1_text:'¿Se observa una dificultad durante la actividad?',q1_a:'Se detiene o pide ayuda',q1_b:'Completa la actividad sin ayuda',q1_c:'No se pudo determinar',q2_text:`¿Qué recurso utiliza durante ${context}?`,q2_a:'Registro en papel',q2_b:'Herramienta digital',q2_c:'Otro recurso / ninguno',q3_text:'¿Qué precio o costo aparece en una fuente consultable?',q3_a:'El documento indica un valor',q3_b:'Se indica que es gratuito',q3_c:'No hay precio visible / no aplica'});
 for(let i=0;i<4;i++)d[`q${i}_why`]='¿Por qué? ¿Puedes contarme un ejemplo?';return d;
}
function fifthSets(){
 const t=S.snap?.team||{}, title=(t.title||'nuestro proyecto').split(':')[0], topic=(t.title||'').toLowerCase();
 let action='usar '+title,problem=['No encuentro información','Me cuesta organizarme','No tengo dificultad'],current=['Pido ayuda','Uso papel','Uso una aplicación'],preferences=['Fácil de usar','Diseño atractivo','Precio accesible'];
 if(/agenda/.test(topic)){action='organizar tus tareas';problem=['Olvido fechas','Pierdo mis anotaciones','No tengo dificultad'];current=['Uso agenda de papel','Uso una aplicación','No uso agenda'];preferences=['Espacio para escribir','Recordatorios con QR','Diseño personalizado'];}
 else if(/circular|tienda/.test(topic)){action='conseguir objetos reutilizados';problem=['No sé qué hay disponible','No sé en qué estado están','No tengo dificultad'];current=['Compro objetos nuevos','Busco objetos usados','Intercambio con conocidos'];preferences=['Fotos claras','Estado y precio del objeto','Opción de intercambio'];}
 else if(/préstamo|prestamo/.test(topic)){action='pedir prestados materiales escolares';problem=['No sé quién puede prestarme','Olvido devolverlos','No tengo dificultad'];current=['Pido a un compañero','Pido a la docente','No suelo pedir materiales'];preferences=['Ver materiales disponibles','Fecha de devolución','Registro de quién los tiene'];}
 else if(/calculadora|costo|ganancia/.test(topic)){action='calcular el precio de un producto';problem=['No sé sumar los costos','No sé cuánto ganar','No tengo dificultad'];current=['Calculo en papel','Uso calculadora','Pido ayuda'];preferences=['Imágenes de los materiales','Cálculo automático','Explicación paso a paso'];}
 else if(/personaliza|etiqueta|llavero/.test(topic)){action='elegir útiles o accesorios personalizados';problem=['No encuentro el diseño que quiero','No veo el precio antes de pedir','No tengo dificultad'];current=['Compro en una tienda','Pido un diseño personalizado','No suelo comprarlos'];preferences=['Elegir colores y dibujos','Poner mi nombre','Ver el precio final'];}
 else if(/perdidos/.test(topic)){action='encontrar un objeto perdido';problem=['No sé dónde buscar','No puedo reconocer mi objeto','No tengo dificultad'];current=['Pregunto a la docente','Reviso objetos perdidos','Pregunto a compañeros'];preferences=['Foto del objeto','Categoría del objeto','Lugar donde fue encontrado'];}
 else if(/ruido|noisemap/.test(topic)){action='trabajar en un ambiente tranquilo';problem=['No escucho las indicaciones','Me cuesta concentrarme','No tengo dificultad'];current=['Pido que bajen la voz','Busco un lugar tranquilo','Continúo mi actividad'];preferences=['Mapa de lugares tranquilos','Aviso visual del ruido','Consejos para bajar el ruido'];}
 else if(/humedad/.test(topic)){action='saber cuándo regar una planta';problem=['No sé si necesita agua','Riego demasiadas veces','No tengo dificultad'];current=['Toco la tierra','Riego por horario','Pregunto a otra persona'];preferences=['Indicador de humedad','Aviso de riego','Instrucciones sencillas'];}
 else if(/agua|waterwatch/.test(topic)){action='cuidar el agua';problem=['Olvido cerrar la llave','No identifico cuánto se desperdicia','No tengo dificultad'];current=['Cierro la llave mientras no la uso','Aviso cuando hay fugas','No llevo un registro'];preferences=['Recordatorios visuales','Registro de hábitos','Retos de ahorro'];}
 else if(/ecocraft|recuperado|reciclad/.test(topic)){action='elegir productos hechos con material reutilizado';problem=['No encuentro productos que me gusten','No sé si serán resistentes','No tengo dificultad'];current=['Compro productos nuevos','Reutilizo lo que tengo','Compro productos reutilizados'];preferences=['Resistencia','Diseño y colores','Historia del material'];}
 else if(/vivero|plantas/.test(topic)){action='elegir y cuidar una planta';problem=['No sé cuál elegir','No conozco sus cuidados','No tengo dificultad'];current=['Pregunto a alguien','Busco información','Uso una guía de cuidados'];preferences=['Foto y nombre de la planta','Precio y disponibilidad','Guía de cuidados'];}
 return [
 [[`¿A qué grupo perteneces como posible usuario de ${title}?`,`¿Qué tipo de usuario serías de ${title}?`],['Estudiante','Docente o personal escolar','Familiar / otro']],
 [[`¿Qué te resulta más difícil al ${action}?`,`¿Cuál es tu principal dificultad para ${action}?`],problem],
 [[`¿Cómo haces actualmente para ${action}?`,`¿Qué haces hoy cuando necesitas ${action}?`],current],
 [[`¿Qué característica prefieres en una solución para ${action}?`,`¿Qué sería más importante para ti al usar ${title}?`],preferences],
 [[`¿Cuánto pagarías por una propuesta como ${title}?`,`¿Qué precio considerarías para una solución que te ayude a ${action}?`],['Menos de $1','De $1 a $3','Más de $3 / no aplica']]
 ];
}

function interviewSets(){
 const t=S.snap?.team||{}, title=(t.title||'nuestro proyecto').split(':')[0],full=(t.title+' '+t.problem+' '+t.solution).toLowerCase();
 let action='realizar la actividad de '+title, difficulties=['Encontrar información','Organizar mis actividades','Ninguna / otra'],features=['Facilidad de uso','Información clara','Ahorro de tiempo'],current=['En papel','Con una herramienta digital','No llevo un registro'];
 if(/wolves/.test(full)){action='utilizar una plataforma de bienestar escolar';difficulties=['Encontrar las actividades','Saber cómo pedir acompañamiento','Ninguna / prefiero no responder'];features=['Actividades breves de autocuidado','Botón para solicitar apoyo adulto','Instrucciones claras'];current=['Converso con un adulto de confianza','Utilizo recursos de bienestar','No uso una herramienta / prefiero no responder'];}
 else if(/accessflow|congestión/.test(full)){action='ingresar a la escuela';difficulties=['Esperar en la fila','Encontrar el acceso despejado','Ninguna / otra'];features=['Horarios menos congestionados','Información del acceso','Recorrido claro'];current=['Llego caminando','Llego en vehículo familiar','Llego en transporte escolar'];}
 else if(/biovision|crecimiento/.test(full)){action='seguir el crecimiento de una planta';difficulties=['Recordar cuándo medir','Comparar fotografías','Ninguna / otra'];features=['Fotos por fecha','Gráfico de medidas','Recordatorios de cuidado'];}
 else if(/actapro|reuniones/.test(full)){action='registrar acuerdos de reuniones';difficulties=['Recordar los acuerdos','Identificar responsables','Ninguna / otra'];features=['Lista de acuerdos','Responsables y fechas','Recordatorios'];}
 else if(/patternwatch|incidencias/.test(full)){action='consultar situaciones que se repiten en la escuela';difficulties=['Encontrar registros','Comparar lugares y fechas','Ninguna / otra'];features=['Filtro por lugar','Resumen por fecha','Categorías claras'];}
 else if(/energy|energ/.test(full)){action='cuidar el uso de energía en el aula';difficulties=['Recordar apagar equipos','Saber qué consume energía','Ninguna / otra'];features=['Recordatorios de apagado','Iluminación de bajo consumo','Resumen de hábitos'];}
 else if(/circularmarket|intercambio/.test(full)){action='intercambiar objetos que todavía sirven';difficulties=['Encontrar a quién le sirvan','Saber qué objetos están disponibles','Ninguna / otra'];features=['Fotos de los objetos','Estado del objeto','Historial del intercambio'];current=['Los guardo','Los dono o intercambio','Los desecho'];}
 else if(/snack/.test(full)){action='elegir un snack escolar';difficulties=['Encontrar un precio accesible','Encontrar ingredientes que prefiero','Ninguna / otra'];features=['Sabor','Precio','Ingredientes'];current=['Lo traigo de casa','Lo compro en la escuela','No suelo comer snacks'];}
 else if(/biotrack|especies|zoobot/.test(full)){action='consultar los cuidados de una especie de la Zoobotánica';difficulties=['Saber qué cuidado falta','Encontrar el historial','Ninguna / otra'];features=['Fotografías con fecha','Registro de cuidados','Avisos de tareas pendientes'];}
 else if(/emergency|emergencia/.test(full)){action='practicar qué hacer en una emergencia';difficulties=['Recordar el protocolo','Elegir la acción adecuada','Ninguna / otra'];features=['Escenarios claros','Explicación de cada decisión','Práctica guiada'];current=['Leo el protocolo','Participo en simulacros','Todavía no he practicado'];}
 else if(/foodwaste|desperdicio/.test(full)){action='evitar desperdiciar alimentos en el comedor';difficulties=['Elegir la cantidad adecuada','Reconocer qué alimentos sobran','Ninguna / otra'];features=['Registro por alimento','Comparación por día','Consejos para reducir desperdicios'];current=['Observo lo que sobra','Registro las sobras','No llevo un registro'];}
 return [
 [[`¿Qué relación tienes con la actividad de ${action}?`,`¿En qué grupo estás como posible usuario de ${title}?`],['Estudiante','Docente o personal escolar','Familiar / otro']],
 [[`¿Cómo haces actualmente para ${action}?`,`¿Qué recurso utilizas hoy para ${action}?`],current],
 [[`¿Qué te resulta más difícil al ${action}?`,`¿Qué problema encuentras cuando intentas ${action}?`],difficulties],
 [[`¿Qué ayuda necesitas para ${action}?`,`¿Qué te ayudaría a mejorar tu experiencia al ${action}?`],features],
 [[`¿Qué característica valorarías más en ${title}?`,`¿Qué debería tener una solución para ayudarte a ${action}?`],features],
 [[`¿Cuánto pagas actualmente para ${action}?`,`¿Qué presupuesto considerarías para una solución como ${title}?`],['No pago actualmente / no aplica','Puedo indicar un valor en dólares','No lo sé; tendría que consultarlo']]
 ];
}
function suggestionSets(){return isFive()?fifthSets():isSix()?interviewSets():seventhSets();}
function suggestions(){const d={technique:'encuesta'};suggestionSets().forEach(([questions,answers],i)=>{d[`q${i}_text`]=questions[0];answers.forEach((a,j)=>d[`q${i}_${'abc'[j]}`]=a);d[`q${i}_why`]='¿Por qué? ¿Puedes contarme un ejemplo?';});return d;}
function questionChoices(i,present){if(present||teacher)return '';return `<label class="market-field">Elige una pregunta de ejemplo<select data-question-choice="${i}" ${enabled()?'':'disabled'}><option value="">Seleccionar o escribir mi propia pregunta</option>${suggestionSets()[i][0].map((v,j)=>`<option value="${j}">${E(v)}</option>`).join('')}</select></label>`;}

function seventhSets(){
 const t=S.snap?.team||{},title=(t.title||'nuestro proyecto').split(':')[0],topic=(t.title||'').toLowerCase();
 let action='realizar la actividad de '+title,current=['Con apoyo de otra persona','Con una herramienta digital','Sin una herramienta específica'],difficulty=['Encontrar información','Organizar mis actividades','Otra / ninguna'],features=['Facilidad de uso','Información clara','Ahorro de tiempo'];
 if(/metastartup|feria/.test(topic)){action='visitar una feria de emprendimientos';current=['Visito stands presenciales','Reviso proyectos en línea','No he visitado una feria'];difficulty=['Encontrar proyectos que me interesen','Entender qué ofrece cada proyecto','Otra / ninguna'];features=['Ver el prototipo','Escuchar el pitch','Hacer preguntas al equipo'];}
 else if(/pitch/.test(topic)){action='preparar una presentación de emprendimiento';current=['Practico con mi equipo','Me grabo y reviso','No suelo practicar'];difficulty=['Controlar mis nervios','Responder preguntas','Otra / ninguna'];features=['Ensayar con una audiencia','Recibir comentarios claros','Controlar el tiempo'];}
 else if(/serviceprice|cotiz/.test(topic)){action='calcular el precio de un servicio';current=['Calculo en papel','Uso una hoja de cálculo','Pido ayuda'];difficulty=['Calcular el tiempo de trabajo','Sumar costos y ganancia','Otra / ninguna'];features=['Desglose de costos','Comparación de precios','Cálculo automático'];}
 else if(/biotwin|gemelo/.test(topic)){action='consultar el estado de una zona de la Zoobotánica';current=['Visito la zona','Pregunto al responsable','Reviso registros'];difficulty=['Encontrar datos actualizados','Relacionar especies y cuidados','Otra / ninguna'];features=['Mapa de la zona','Historial de cuidados','Avisos de incidencias'];}
 else if(/cafeter/.test(topic)){action='elegir y pedir alimentos en la cafetería';current=['Reviso el menú disponible','Pregunto en el bar','Llevo alimentos de casa'];difficulty=['Conocer ingredientes y precios','Esperar para realizar un pedido','Otra / ninguna'];features=['Ingredientes y precio claros','Configurar mi pedido','Reservar con anticipación'];}
 else if(/ecotour|recorrido/.test(topic)){action='recorrer la Zoobotánica';current=['Sigo una visita guiada','Recorro por mi cuenta','Consulto carteles'];difficulty=['Encontrar las estaciones','Comprender la información','Otra / ninguna'];features=['Mapa con estaciones','Información mediante QR','Retos interactivos'];}
 else if(/focusflow|carga acad|planificador/.test(topic)){action='organizar la carga de tareas de la semana';current=['Uso una agenda','Uso una aplicación','Reviso cada asignatura por separado'];difficulty=['Estimar cuánto tarda cada tarea','Repartir el trabajo entre días','Otra / ninguna'];features=['Ver pendientes juntos','Recordatorios de fechas','Distribuir el tiempo'];}
 else if(/habitatguard|hábitat/.test(topic)){action='revisar los cuidados de un hábitat animal';current=['Uso una lista de revisión','Pregunto al responsable','Reviso registros anteriores'];difficulty=['Saber qué cuidado priorizar','Registrar lo observado','Otra / ninguna'];features=['Lista de criterios','Semáforo de cuidados','Evidencias con fecha'];}
 else if(/harvest|cosecha/.test(topic)){action='registrar el destino de una cosecha';current=['Anoto cantidades en papel','Uso una hoja de cálculo','Pregunto a la persona responsable'];difficulty=['Conocer el destino de cada parte','Calcular cuánto se aprovecha','Otra / ninguna'];features=['Cantidades y destinos claros','Historial de la cosecha','Porcentaje aprovechado'];}
 else if(/microclima/.test(topic)){action='consultar temperatura y humedad de una zona';current=['Leo un termómetro o sensor','Consulto registros','Pregunto al responsable'];difficulty=['Comparar datos de distintas horas','Entender los cambios','Otra / ninguna'];features=['Gráficos por horario','Datos de temperatura y humedad','Avisos comprensibles'];}
 else if(/energ/.test(topic)){action='cuidar el uso de energía por zonas';current=['Reviso equipos encendidos','Anoto hábitos de uso','No llevo un registro'];difficulty=['Detectar usos innecesarios','Comparar zonas y horarios','Otra / ninguna'];features=['Resumen por zona','Acciones de ahorro','Recordatorios de apagado'];}
 return [
 [[`¿Qué relación tienes con la actividad de ${action}?`,`¿Qué tipo de usuario serías de ${title}?`],['Estudiante','Docente o personal escolar','Familiar / visitante']],
 [[`¿Cómo haces actualmente para ${action}?`,`¿Qué haces hoy cuando necesitas ${action}?`],current],
 [[`¿Qué te resulta más difícil al ${action}?`,`¿Cuál es tu principal dificultad para ${action}?`],difficulty],
 [[`¿Con qué frecuencia necesitas ayuda para ${action}?`,`¿Con qué frecuencia encuentras una dificultad al ${action}?`],['Con frecuencia','Algunas veces','Nunca / no aplica']],
 [[`¿Qué característica valorarías más en ${title}?`,`¿Qué sería más útil en una solución para ${action}?`],features],
 [[`¿Cómo preferirías acceder a una herramienta para ${action}?`,`¿En qué formato te resultaría más cómodo usar ${title}?`],['Desde una tableta o celular','Desde una computadora','Con una guía impresa / apoyo']],
 [[`¿Qué presupuesto considerarías para usar una propuesta como ${title}?`,`¿Qué rango pagarías por una solución para ${action}?`],['Sin pago directo / no aplica','Hasta $3','Más de $3']],
 [[`Si estuviera disponible, ¿qué interés tendrías en probar ${title}?`,`¿Qué tan dispuesto estarías a probar una solución para ${action}?`],['Me interesa probarla','Necesito conocer más','No la utilizaría / no aplica']]
 ];
}
function techniquePicker(present){const d=content();if(present||teacher)return `<p><b>Técnica principal:</b> ${d.technique==='entrevista'?'Entrevista':'Observación'}</p>${author('technique',present)}`;return `<div class="techniques" role="group" aria-label="Técnica principal">${[['encuesta','Encuesta'],['entrevista','Entrevista'],['observacion','Observación']].map(([v,l])=>`<label><input type="radio" name="technique" value="${v}" data-technique ${d.technique===v?'checked':''} ${enabled()?'':'disabled'}>${l}</label>`).join('')}</div>`;}
function targetField(key,label,present){const d=content(),names=[0,1,2,3].map(i=>d[`audience${i}_name`]).filter(Boolean);return `${!present&&!teacher&&names.length?`<label class="market-field">Elegir un público de nuestra rueda<select data-public-target="${key}" ${enabled()?'':'disabled'}><option value="">Seleccionar un público</option>${names.map(n=>`<option value="${E(n)}" ${d[key]===n?'selected':''}>${E(n)}</option>`).join('')}</select></label>`:''}${field(key,label,'Describe el público sin identificar a una persona por su nombre.',present)}`;}
function interviewExamples(){const topic=seventhSets();return [
 [`Cuéntanos qué te resulta más difícil: ${topic[2][0][0].replace(/^¿|\?$/g,'')}. ¿Puedes dar un ejemplo?`,`¿Cómo resolviste la última dificultad relacionada con ${S.snap.team.title}?`],
 [`¿Qué cambiarías de tu experiencia con ${S.snap.team.title} y por qué?`,`¿Qué debería tener nuestra propuesta para ayudarte y por qué?`],
 ['¿Qué alternativa utilizas actualmente y qué te gusta de ella?','¿Cómo te gustaría que funcionara nuestra solución?'],
 ['¿Qué te haría confiar en esta propuesta?','¿Qué presupuesto considerarías y qué tendría que ofrecer a cambio?']
 ];}
function interviewView(present){return `<p class="slide-tip">Dos preguntas abiertas obligatorias. Pueden añadir la tercera y cuarta. Registren las respuestas al aplicar la entrevista.</p><div class="interview-context">${targetField('interview_target','Público al que entrevistamos',present)}${field('interview_media','Enlace del video o audio','https://…',present,true)}${safeLink(content().interview_media)}</div><div class="questions-grid">${[0,1,2,3].map(i=>{if(present&&!content()['interview'+i])return '';return `<article class="question-card"><h3>Pregunta ${i+1}${i>1?' · opcional':''}</h3>${!present&&!teacher?`<label class="market-field">Pregunta sugerida<select data-interview-choice="${i}" ${enabled()?'':'disabled'}><option value="">Elegir o escribir mi pregunta</option>${interviewExamples()[i].map((v,j)=>`<option value="${j}">${E(v)}</option>`).join('')}</select></label>`:''}${field('interview'+i,'Pregunta abierta',interviewExamples()[i][0],present)}</article>`;}).join('')}</div>`;}
function empathyView(present){const d=content(),targetIndex=[0,1,2,3].find(i=>d[`audience${i}_name`]===d.empathy_target),image=d[`audience${targetIndex}_image`];return `${targetField('empathy_target','Público observado',present)}<div class="empathy-meta">${field('empathy_place','Lugar de observación','¿Dónde observaron?',present,true)}${field('empathy_date','Fecha y momento','¿Cuándo observaron?',present,true)}</div><div class="empathy-map"><article class="empathy-think">${field('empathy_think','☁ ¿Qué piensa y siente?','Indiquen lo que la persona expresó. Si es una suposición, escriban «Por confirmar».',present)}</article><article class="empathy-hear">${field('empathy_hear','♧ ¿Qué oye?','Mensajes, indicaciones o comentarios que escucha.',present)}</article><div class="empathy-person">${/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(image||'')?`<img src="${image}" alt="Público observado">`:'<span aria-hidden="true">♙</span>'}<b>${E(d.empathy_target||'Nuestro público')}</b></div><article class="empathy-see">${field('empathy_see','◉ ¿Qué ve?','Objetos, personas y situaciones de su entorno.',present)}</article><article class="empathy-do">${field('empathy_do','☏ ¿Qué dice y hace?','Acciones observadas y palabras escuchadas.',present)}</article></div>${field('empathy_basis','Evidencia y aspectos por confirmar','Separamos hechos observados, frases escuchadas y supuestos que necesitamos confirmar.',present)}`;}
function fingerprint(text){let a=2166136261,b=333555777;for(let i=0;i<text.length;i++){a=Math.imul(a^text.charCodeAt(i),16777619);b=Math.imul(b^text.charCodeAt(i),2246822519);}return (a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');}
function surveyGroups(){const groups=new Map();for(const r of S.snap?.responses||[]){if(r.kind!=='real'||r.technique!=='encuesta'||!Array.isArray(r.instrument)||!Array.isArray(r.answers)||r.instrument.length!==r.answers.length||!r.instrument.length)continue;if(!r.instrument.every((x,i)=>typeof x.text==='string'&&Array.isArray(x.options)&&x.options.length===3&&Number.isInteger(r.answers[i]?.choice)&&r.answers[i].choice>=0&&r.answers[i].choice<3))continue;const normalized=r.instrument.map(x=>({text:x.text,options:x.options})),signature=JSON.stringify(normalized);if(!groups.has(signature))groups.set(signature,{id:fingerprint(signature),instrument:normalized,records:[],at:r.at});groups.get(signature).records.push(r);}return [...groups.values()];}
function chartCounts(group,index){return [0,1,2].map(choice=>group.records.filter(r=>r.answers[index].choice===choice).length);}
function analysisSuggestion(group){const n=group.records.length;return group.instrument.map((q,i)=>{const counts=chartCounts(group,i),max=Math.max(...counts),winners=counts.map((v,j)=>v===max?j:-1).filter(j=>j>=0);return `Pregunta ${i+1}: ${winners.length>1?'hubo un empate entre '+winners.map(j=>'«'+q.options[j].slice(0,32)+'»').join(' y '):'la opción más seleccionada fue «'+q.options[winners[0]].slice(0,32)+'»'}. ${max} de ${n} personas (${Math.round(max/n*100)} %) eligieron ${winners.length>1?'cada una de esas opciones':'esa opción'}.`;}).join('\n')+'\nEstos resultados describen solo a las personas encuestadas. Como equipo, expliquen qué decisión tomarán para mejorar el proyecto y qué falta investigar.';}
function resultPages(){if(content().technique==='entrevista'){const records=(S.snap?.responses||[]).filter(r=>r.kind==='real'&&r.technique==='entrevista');return records.length?records.flatMap(r=>Array.from({length:Math.ceil(r.instrument.length/2)},(_,i)=>({interview:r,start:i*2}))):[{empty:true,interview:true}];}const groups=surveyGroups();return groups.length?groups.flatMap((g,version)=>[...Array.from({length:Math.ceil(g.instrument.length/2)},(_,i)=>({group:g,version:version+1,start:i*2})),{group:g,version:version+1,analysis:true}]):[{empty:true}];}
function chart(group,index){const q=group.instrument[index],counts=chartCounts(group,index),n=group.records.length;return `<article class="result-chart"><h3>${index+1}. ${E(q.text)}</h3><div class="chart-bars" role="img" aria-label="${E(q.options.map((v,j)=>v+': '+counts[j]+' de '+n).join('; '))}">${q.options.map((v,j)=>`<div class="chart-row"><div><span>${E(v)}</span><b>${counts[j]} · ${Math.round(counts[j]/n*100)} %</b></div><div class="chart-track"><span style="width:${counts[j]/n*100}%"></span></div></div>`).join('')}</div><p class="slide-tip">Base: ${n} encuestas reales de esta versión.</p></article>`;}
function resultsSlide(index,present){const page=resultPages()[index-30]||{empty:true};let body='',title='Resultados de nuestra encuesta';if(page.empty)body='<div class="results-empty"><h3>Todavía no hay aplicaciones reales</h3><p>Completen el instrumento, guarden y registren sus aplicaciones. Los ensayos se conservan como práctica y no se incluyen en los resultados.</p></div>';else if(page.interview){title='Lo que escuchamos en la entrevista';const r=page.interview;body=`<p><b>Público:</b> ${E(r.instrument[0]?.audience||'No indicado')}</p>${safeLink(r.instrument[0]?.media)}<div class="questions-grid">${r.instrument.slice(page.start,page.start+2).map((item,j)=>`<article class="question-card"><h3>${E(item.text)}</h3><p class="presentation-text">${E(r.answers[page.start+j]?.text??((item.options?.[r.answers[page.start+j]?.choice]||'')+' '+(r.answers[page.start+j]?.why||'')))}</p></article>`).join('')}</div>`;}else{const g=page.group;body=`<p class="result-base"><b>Versión ${page.version}</b> · ${g.records.length} encuestas reales · ${g.instrument.length} preguntas</p>`;if(page.analysis){title='Analizamos para decidir';body+=`${!present&&!teacher?`<details class="analysis-help"><summary>Ver sugerencia basada en los resultados</summary><p>${E(analysisSuggestion(g)).replace(/\n/g,'<br>')}</p>${button('Usar esta sugerencia y editar','analysis',false,`data-group="${g.id}" ${enabled()?'':'disabled'}`)}</details>`:''}${field('analysis_'+g.id,'Nuestro análisis y decisión','¿Qué descubrimos? ¿Qué cambiaremos en el proyecto? ¿Qué nos falta confirmar?',present)}`;}else body+=`<div class="results-grid">${g.instrument.slice(page.start,page.start+2).map((_,j)=>chart(g,page.start+j)).join('')}</div>`;}
return `<section class="market-deck results-deck"><header class="slide-head"><div><p class="eyebrow">INVESTIGACIÓN DE MERCADO Y PÚBLICO OBJETIVO</p><h2>${title}</h2><p class="project-line">${E(projectContext())}</p></div><span class="tag">${slides().indexOf(index)+1}</span></header>${body}<footer class="slide-footer"><span>Eight Academy · Emprendimiento</span><span>${slides().indexOf(index)+1} / ${slides().length}</span></footer></section>`;}


async function loadPortfolio(){
 S.ods=await rpc('aula_student_snapshot');if(S.ods.status!=='ok')throw Error('Ingresa primero a Mi aula con tu nombre y equipo.');
 try{S.snap=await rpc('aula_market_snapshot');}catch(err){const t=S.ods.team,u=S.ods.user;S.snap={team:{grade:u.grade,parallel:u.parallel,group:u.group,name:t.name,title:t.project.title},work:{content:{},version:null,status:'draft'},publication:{state:'draft'},members:[],responses:[]};if(!/todavía no habilitó/.test(err.message))note('No se pudo cargar Investigación de mercado. Pulsa Actualizar para volver a intentarlo.',true);}
 if(coverPilot()){window.PortfolioCover.load(await rpc('aula_portfolio_cover'));window.PortfolioProblem.load(await rpc('aula_portfolio_problem'));S.slide=-2;}
 S.mode='presentacion';if(!slides().includes(S.slide))S.slide=slides()[0]??-1;
}
function pilotAudienceFrame(){const c=window.PortfolioCover.colors(),d=content(),active=[0,1,2,3].filter(i=>d[`audience${i}_name`]||d[`audience${i}_image`]),slots=active.length?active:[0,1,2,3],n=slots.length,positions=n===1?[[73,50]]:n===2?[[20,50],[80,50]]:n===3?[[20,23],[80,23],[50,82]]:[[20,23],[80,23],[20,78],[80,78]],hub=n===1?[30,50]:[50,50];return `<section class="cover-slide cover-${c.style} audience-presentation" aria-label="Público objetivo" style="--cover-bg:${c.background};--cover-primary:${c.primary};--cover-accent:${c.accent};--cover-text:${c.text}"><div class="audience-slide-content"><h2>Público objetivo</h2><div class="wheel wheel-adaptive"><svg class="spokes" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${positions.map(([x,y])=>`<path d="M${hub[0]} ${hub[1]}L${x} ${y}" stroke="currentColor" stroke-width=".35" fill="none"/>`).join('')}</svg><div class="wheel-hub" style="left:${hub[0]}%;top:${hub[1]}%"><strong>Público<br>objetivo</strong></div>${slots.map((i,j)=>{const image=d[`audience${i}_image`],safe=/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(image||'');return `<article class="audience-card" style="left:${positions[j][0]}%;top:${positions[j][1]}%"><div class="audience-picture">${safe?`<img src="${image}" alt="${E(d[`audience${i}_name`]||'Público objetivo')}">`:'<span>Imagen</span>'}</div><p>${E(d[`audience${i}_name`]||'Por completar')}</p></article>`;}).join('')}</div></div></section>`;}
function pilotAudienceView(present){if(present)return pilotAudienceFrame();return `<div class="panel"><h2>Rueda del público objetivo</h2><p>Usen la misma rueda de la actividad: imagen y nombre debajo. Los cambios se guardan también en su actividad.</p><div class="public-cards">${[0,1,2,3].map(i=>audience(i,false)).join('')}</div></div><div class="cover-preview"><p>VISTA PREVIA · 16:9</p>${pilotAudienceFrame()}</div>`;}
const portfolioGoalNames=['Fin de la pobreza','Hambre cero','Salud y bienestar','Educación de calidad','Igualdad de género','Agua limpia y saneamiento','Energía asequible y no contaminante','Trabajo decente y crecimiento económico','Industria, innovación e infraestructura','Reducción de las desigualdades','Ciudades y comunidades sostenibles','Producción y consumo responsables','Acción por el clima','Vida submarina','Vida de ecosistemas terrestres','Paz, justicia e instituciones sólidas','Alianzas para lograr los objetivos'];
let pilotODSBlock=0;
function odsSlide(present=true){const edit=portfolio&&S.mode==='edit'&&!present&&S.ods?.publication?.state==='available',d=edit?(S.odsDraft||S.ods?.work?.content||{}):(S.ods?.work?.content||{}),goals=portfolioGoalNames;if(coverPilot())return pilotODSView(d,edit);return `<section class="market-deck"><header class="slide-head"><div><p class="eyebrow">MI PORTAFOLIO · NUESTRO PROYECTO</p><h2>ODS vinculados al proyecto</h2><p class="project-line">${E(projectContext())}</p></div><span class="tag">01</span></header><div class="portfolio-ods">${[0,1,2,3].map(i=>{const id=d.ods?.[i];if(!edit&&(!Number.isInteger(id)||id<1||id>17))return '';return `<article class="question-card">${id?`<img src="semana8-quinto/ods-oficial-${String(id).padStart(2,'0')}.png" alt="ODS ${id}: ${E(goals[id-1])}">`:''}${edit?`<label>ODS ${i+1}<select data-portfolio-ods="${i}"><option value="">Elegir ODS</option>${goals.map((name,j)=>`<option value="${j+1}" ${id===j+1?'selected':''} ${(d.ods||[]).some((v,k)=>k!==i&&v===j+1)?'disabled':''}>${j+1}. ${E(name)}</option>`).join('')}</select></label><label>Explicación<textarea data-portfolio-reason="${i}" maxlength="250">${E(d.reasons?.[i]||'')}</textarea></label><label><input type="radio" name="portfolio-principal" data-portfolio-principal="${i}" ${d.principal===i?'checked':''}>ODS principal</label>`:`<h3>${E(goals[id-1])}${d.principal===i?' · ODS principal':''}</h3><p class="presentation-text">${E(d.reasons?.[i]||'')}</p>`}</article>`;}).join('')}</div>${S.snap.team.grade===7&&(edit||d.indicator)?`<div class="portfolio-indicator"><b>Qué mediremos</b>${edit?`<input data-portfolio-indicator maxlength="150" value="${E(d.indicator||'')}">`:`<p>${E(d.indicator)}</p>`}</div>`:''}<footer class="slide-footer"><span>Eight Academy · Emprendimiento</span><span>1 / ${slides().length}</span></footer></section>`;}

function pilotODSFrame(d){const c=window.PortfolioCover.colors(),selected=[0,1,2,3].filter(i=>Number.isInteger(d.ods?.[i])&&d.ods[i]>=1&&d.ods[i]<=17);return `<section class="cover-slide cover-${c.style} ods-presentation" aria-label="ODS vinculadas al proyecto" style="--cover-bg:${c.background};--cover-primary:${c.primary};--cover-accent:${c.accent};--cover-text:${c.text}"><div class="ods-slide-content"><h2>ODS vinculadas al proyecto</h2><div class="ods-slide-cards" style="--ods-count:${Math.max(1,selected.length)}">${selected.map(i=>`<article><div class="ods-slide-image"><img src="semana8-quinto/ods-oficial-${String(d.ods[i]).padStart(2,'0')}.png" alt="ODS ${d.ods[i]}: ${E(portfolioGoalNames[d.ods[i]-1])}"></div><p style="font-size:${(d.reasons?.[i]||'').length>160?'1.4cqw':'1.8cqw'}">${E(d.reasons?.[i]||'')}</p></article>`).join('')||'<p class="ods-slide-empty">Aquí aparecerán las ODS que seleccione el equipo.</p>'}</div></div></section>`;}
function pilotODSView(d,edit){if(!edit)return pilotODSFrame(d);const i=pilotODSBlock;return `<div class="cover-design-layout"><aside class="cover-editor" aria-label="Editar ODS"><p class="eyebrow">HOJA 3 · ODS</p><h2>Imagen y explicación</h2><nav class="cover-editor-tabs ods-editor-tabs" aria-label="Recuadros ODS">${[0,1,2,3].map(n=>`<button type="button" data-pilot-ods-block="${n}" aria-pressed="${i===n}">ODS ${n+1}</button>`).join('')}</nav><label>ODS vinculada<select data-portfolio-ods="${i}"><option value="">Elegir ODS</option>${portfolioGoalNames.map((name,j)=>`<option value="${j+1}" ${d.ods?.[i]===j+1?'selected':''} ${(d.ods||[]).some((v,k)=>k!==i&&v===j+1)?'disabled':''}>${j+1}. ${E(name)}</option>`).join('')}</select></label><label>Explicación sencilla<textarea data-portfolio-reason="${i}" maxlength="250" rows="5" placeholder="¿Cómo aporta nuestro proyecto a esta ODS?">${E(d.reasons?.[i]||'')}</textarea></label><p class="muted">Se conservan las ODS y explicaciones que ya guardaron. Los logos aparecen al seleccionarlas.</p></aside><div class="cover-preview"><p>VISTA PREVIA · 16:9</p><div data-pilot-ods-preview>${pilotODSFrame(d)}</div></div></div>`;}

function portfolioCanEdit(){if(S.slide===-2||S.slide===-3)return coverPilot();return S.slide===-1?S.ods?.publication?.state==='available':S.snap?.publication?.state==='available';}
function odsDraft(){if(!S.odsDraft)S.odsDraft=JSON.parse(JSON.stringify(S.ods?.work?.content||{ods:[null,null,null,null],reasons:['','','',''],principal:0,indicator:''}));return S.odsDraft;}
async function savePortfolioChanges(){if(S.slide===-3){window.PortfolioProblem.load(await rpc('aula_portfolio_problem',window.PortfolioProblem.payload()));}else if(S.slide===-2){window.PortfolioCover.load(await rpc('aula_portfolio_cover',window.PortfolioCover.payload()));}else if(S.slide===-1){if(!portfolioCanEdit())throw Error('Esta actividad está cerrada.');S.ods=await rpc('aula_student_save_work',{p_content:S.odsDraft||S.ods.work.content,p_submit:S.ods.work.status==='submitted'});S.odsDraft=null;}else await save(S.snap.work.status==='submitted');S.mode='presentacion';note('Cambios guardados y compartidos con tu equipo y tu docente.');}

function renderPortfolio(){const all=slides(),position=all.indexOf(S.slide);root.innerHTML=`<button type="button" class="button portfolio-exit" data-market="full">Salir de presentación ✕</button><header class="topbar"><a class="brand" href="aula-estudiante.html">Eight Academy <small>Mi portafolio</small></a><a class="button" href="aula-estudiante.html">← Volver a mi aula</a></header><main class="market-container ${S.mode==='presentacion'?'presenting':''} ${coverPilot()?'portfolio-themed':''}" style="${coverPilot()?window.PortfolioCover.theme():''}"><div class="market-heading"><div><p class="eyebrow">${gradeName().toUpperCase()} ${S.snap.team.parallel} · EQUIPO ${S.snap.team.group}</p><h1>Mi portafolio</h1><p>${E(S.snap.team.title)}</p></div></div><div class="notice ${S.error?'notice-error':''}" role="status">${E(S.notice)}</div><div class="market-toolbar"><p>Los trabajos de nuestro equipo, en una sola presentación.</p><div class="market-actions">${all.length&&portfolioCanEdit()?button(S.mode==='edit'?'Guardar cambios':S.slide===-2?'Editar portada':S.slide===-3?'Editar problema':'Editar',S.mode==='edit'?'portfolio-save':'portfolio-edit',true,S.busy?'disabled':''):''}${S.mode==='edit'?button('Cancelar','portfolio-cancel'):''}${button('Actualizar','refresh')}${all.length?button('Imprimir / guardar PDF','print')+button('⛶ Pantalla completa','full'):''}</div></div>${S.mode==='edit'&&S.slide!==-1&&S.slide!==-2&&S.slide!==-3?`<div class="market-toolbar"><label>¿Quién va a aportar?<select id="market-actor"><option value="">Selecciona tu nombre</option>${S.snap.members.map(m=>`<option value="${m.id}" ${S.actor===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label></div>`:''}${all.length?`<nav class="slide-tabs" aria-label="Contenido del portafolio">${all.map((i,j)=>button((j+1)+'. '+slideLabel(i),'slide',false,`data-index="${i}" ${i===S.slide?'aria-current="page"':''}`)).join('')}</nav><div class="market-live">${slide(S.slide,S.mode==='presentacion')}</div><nav class="market-page-nav">${button('← Anterior','slide',false,`data-index="${all[position-1]}" ${position===0?'disabled':''}`)}<span>Diapositiva ${position+1} de ${all.length}</span>${button('Siguiente →','slide',true,`data-index="${all[position+1]}" ${position===all.length-1?'disabled':''}`)}</nav><div class="print-decks">${all.map(i=>slide(i,true)).join('')}</div>`:'<section class="panel empty"><h2>Tu portafolio está por comenzar</h2><p>Aquí aparecerán las actividades que tu equipo vaya guardando.</p><a class="button" href="aula-estudiante.html">Ir a mi aula</a></section>'}</main>`;if(coverPilot())window.PortfolioCover.fit(root);}

function participation(){if(!teacher)return '';return `<section class="panel market-participation"><h2>Participación del equipo</h2><p class="muted">El nombre se selecciona al aportar desde el dispositivo compartido. Se registra también la sesión que guardó el cambio. Es evidencia de participación para revisar, no una nota automática.</p><div class="participation-grid">${(S.snap.participation||[]).map(m=>`<article><strong>${E(m.name)}</strong><p>${m.contributions} cambios registrados</p></article>`).join('')}</div></section>`;}
const numberSelect=(name,max,value)=>`<select name="${name}" aria-label="${E(name)}"><option value="">Sin evaluar</option>${Array.from({length:max+1},(_,i)=>`<option value="${i}" ${value===i?'selected':''}>${i} / ${max}</option>`).join('')}</select>`;
function rubric(){if(!teacher)return '';const r=S.rubric||S.snap.evaluation||{},individual=r.individual_scores||{},sum=v=>v.some(n=>n===null||n===undefined)?'—':v.reduce((a,b)=>a+b,0);return `<form id="market-rubric" class="panel market-rubric"><h2>Una evaluación · 7 grupales + 3 individuales</h2><div class="rubric-grid">${[['ods_score','Público y necesidad',3,surveyOnly()?'3: públicos pertinentes con imágenes y descripciones claras; 2: falta precisar; 1: información mínima; 0: sin evidencia.':'3: público pertinente, imágenes y tres respuestas coherentes; 2: falta precisar una parte; 1: información mínima; 0: sin evidencia.'],['reasons_score','Instrumento de investigación',2,`2: ${content().technique==='entrevista'?'al menos dos preguntas abiertas, público, respuestas y grabación':content().technique==='observacion'?'mapa completo con evidencia y distinción entre hechos y supuestos':countName()+' preguntas con opciones claras y análisis de resultados'}; 1: evidencia parcial; 0: sin evidencia.`],['teamwork_score','Trabajo en equipo',2,'2: se reparten aportes y revisan juntos; 1: requieren apoyo; 0: no se observa colaboración.']].map(([key,label,max,desc])=>`<div class="rubric-row"><div><h3>${label} · ${max}</h3><p class="muted">${desc}</p></div>${numberSelect(key,max,r[key]??null)}</div>`).join('')}</div><h3>Evaluación individual</h3><p class="muted">Cada criterio vale 1 punto. Sin evaluar no equivale a cero. Valora la evidencia y la participación observada.</p><div class="scroll"><table><thead><tr><th>Integrante</th><th>Orden /1</th><th>Organización /1</th><th>Aporte /1</th><th>Total /10</th></tr></thead><tbody>${S.snap.members.map((m,i)=>{const v=individual[m.id]||{};return `<tr><th>${E(m.name)}</th>${['order','organization','contribution'].map(k=>`<td>${numberSelect(`member_${i}_${k}`,1,v[k]??null)}</td>`).join('')}<td>${sum([r.ods_score,r.reasons_score,r.teamwork_score,v.order,v.organization,v.contribution])} / 10</td></tr>`;}).join('')}</tbody></table></div><label>Retroalimentación<textarea name="feedback" maxlength="3000">${E(r.feedback||'')}</textarea></label><button class="button primary" type="submit" ${S.busy?'disabled':''}>Guardar evaluación</button></form>`;}
function safeLink(url,label='Abrir audio o video'){return /^https:\/\/[^\s<>]+$/.test(url||'')?`<a class="button" href="${E(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';}
function history(){return `<div>${S.snap.responses.map((r,i)=>`<details class="market-history"><summary>Registro ${i+1} · ${r.kind==='real'?'Aplicación real':'Ensayo'} · ${E(r.technique)}</summary><p class="muted">${new Date(r.at).toLocaleString('es-EC')} · Instrumento conservado.</p>${r.instrument[0]?.audience?`<p>Público: ${E(r.instrument[0].audience)}</p>${safeLink(r.instrument[0].media)}`:''}<ol>${r.instrument.map((item,j)=>`<li><b>${E(item.text)}</b><br>${E(r.answers[j]?.text??item.options?.[r.answers[j]?.choice]??'Sin respuesta')}${r.answers[j]?.why?'<br>'+E(r.answers[j].why):''}</li>`).join('')}</ol></details>`).join('')||'<p class="muted">Todavía no hay aplicaciones registradas.</p>'}</div>`;}
function application(){if(S.mode==='presentacion')return '';const d=content(),interview=d.technique==='entrevista';if(d.technique==='observacion')return '';const questions=interview?[0,1,2,3].filter(i=>d['interview'+i]?.trim()).map(i=>d['interview'+i]):questionPurposes().map((_,i)=>d[`q${i}_text`]);return `<section class="panel market-application"><div class="section-heading"><div><h2>Aplicamos nuestra investigación</h2><p>${S.snap.responses.filter(r=>r.kind==='real'&&r.technique===d.technique).length} aplicaciones reales · ${S.snap.responses.filter(r=>r.kind==='ensayo'&&r.technique===d.technique).length} ensayos</p></div>${editable()&&d.technique?button(S.application?'Cerrar registro':'Registrar una aplicación','toggle-application',false,enabled()?'':'disabled'):''}</div><p class="muted">Registren una aplicación por persona, con autorización docente. Los ensayos no se incluyen en los gráficos. No escriban nombres de las personas participantes.</p>${S.application&&editable()?`<form id="response-form" class="response-form"><label>Este registro es<select name="kind"><option value="ensayo" ${S.responseDraft?.kind!=='real'?'selected':''}>Ensayo de práctica</option><option value="real" ${S.responseDraft?.kind==='real'?'selected':''}>Aplicación real autorizada</option></select></label>${questions.map((text,i)=>`<fieldset><legend>${i+1}. ${E(text||'Completa y guarda la pregunta')}</legend>${interview?`<label>Respuesta de la persona<textarea name="text${i}" required maxlength="2000">${E(S.responseDraft?.answers?.[i]?.text||'')}</textarea></label>`:`${['a','b','c'].map((k,j)=>`<label><input required type="radio" name="answer${i}" value="${j}" ${S.responseDraft?.answers?.[i]?.choice===j?'checked':''}>${E(d[`q${i}_${k}`]||'Opción por completar')}</label>`).join('')}<label>Detalle opcional<textarea name="why${i}" maxlength="2000">${E(S.responseDraft?.answers?.[i]?.why||'')}</textarea></label>`}</fieldset>`).join('')}<button class="button primary" type="submit" ${S.busy?'disabled':''}>Guardar esta aplicación</button></form>`:''}${history()}</section>`;}

function render(){if(portfolio&&S.snap){renderPortfolio();return;}const back=teacher?'aula-docente.html?grado='+(S.snap?.team?.grade||+q.get('grado')||7):'aula-estudiante.html';if(!S.snap){root.innerHTML=`<main class="market-container"><a class="button" href="${back}">← Volver al aula</a><section class="panel"><h1>Investigación de mercado y público objetivo</h1><p class="notice ${S.error?'notice-error':''}">${E(S.notice||'Conectando con tu equipo…')}</p></section></main>`;return;}if(!S.snap.team){root.innerHTML=`<main class="market-container"><a class="button" href="${back}">← Panel docente</a><h1>Investigación de mercado y público objetivo</h1><label>Equipo<select data-team><option value="">Selecciona un equipo</option>${S.snap.teams.map(t=>`<option value="${t.id}">${({5:'Quinto',6:'Sexto',7:'Séptimo'})[t.grade||7]} ${t.parallel} · G${t.group} · ${E(t.title)}</option>`).join('')}</select></label></main>`;return;}
 const present=S.mode==='presentacion',status=S.snap.work.status==='submitted'?'Finalizada':Object.keys(S.snap.work.content).length?'En proceso':'Por comenzar';root.innerHTML=`<header class="topbar"><a class="brand" href="${back}">Eight Academy <small>${teacher?'Revisión docente':'Mi aula'}</small></a><a class="button" href="${back}">← ${teacher?'Panel docente':'Mi portafolio'}</a></header><main class="market-container ${present?'presenting':''}"><div class="market-heading"><div><p class="eyebrow">${gradeName().toUpperCase()} ${S.snap.team.parallel} · G${S.snap.team.group} · SEMANA 9</p><h1>Investigación de mercado y público objetivo</h1><p>${E(S.snap.team.title)}</p></div><span class="tag">${status}</span></div><div class="notice ${S.error?'notice-error':''}" role="${S.error?'alert':'status'}">${E(S.notice)}</div>${/tema por (confirmar|definir)/i.test(S.snap.team.title)?'<p class="notice">El tema del equipo está por confirmar. Pueden preparar un borrador; acuerden el tema con la docente antes de finalizar.</p>':''}
 <div class="market-toolbar">${editable()?`<label>¿Quién va a aportar?<select id="market-actor"><option value="">Selecciona tu nombre</option>${S.snap.members.map(m=>`<option value="${m.id}" ${S.actor===m.id?'selected':''}>${E(m.name)}</option>`).join('')}</select></label>`:`<p>${present?'Presentación del equipo':'Revisión del trabajo y participación'}</p>`}<div class="market-actions">${editable()?button('Guardar mi aporte','save',true,enabled()?'':'disabled')+button('Finalizar actividad','submit',false,enabled()?'':'disabled'):''}${button(present?'Volver a la actividad':'Ver presentación', 'mode')}${button('Actualizar','refresh')}${present?button('Imprimir / guardar PDF','print')+button('⛶ Pantalla completa','full'):''}</div></div>
 <nav class="slide-tabs" aria-label="Diapositivas">${slides().map((i,j)=>button((j+1)+'. '+slideLabel(i),'slide',false,`data-index="${i}" ${S.slide===i?'aria-current="page"':''}`)).join('')}</nav><div class="market-live">${slide(S.slide,present)}</div><nav class="market-page-nav">${button('← Anterior','slide',false,`data-index="${slides()[slides().indexOf(S.slide)-1]}" ${S.slide===0?'disabled':''}`)}<span>Diapositiva ${slides().indexOf(S.slide)+1} de ${slides().length}</span>${button('Siguiente →','slide',true,`data-index="${slides()[slides().indexOf(S.slide)+1]}" ${S.slide===slides().at(-1)?'disabled':''}`)}</nav>${present?'':participation()+application()+rubric()}<div class="print-decks">${slides().map(i=>slide(i,true)).join('')}</div></main>`;
}
function patch(key,value){if(!enabled())return;S.pending[key]=value;S.authors[key]=S.actor;}
async function save(submit=false){if(!S.actor)throw Error('Selecciona tu nombre antes de aportar.');if(!editable())throw Error('La actividad está en consulta.');if(surveyOnly()){S.pending.technique='encuesta';S.authors.technique=S.actor;}const groups={};for(const [key,value]of Object.entries(S.pending)){const id=S.authors[key]||S.actor;(groups[id]??={})[key]=value;}
 if(!Object.keys(groups).length)groups[S.actor]={};const ids=Object.keys(groups);for(let i=0;i<ids.length;i++){const id=ids[i],result=await rpc('aula_market_save',{p_member:id,p_changes:groups[id],p_expected:S.snap.work.version,p_submit:submit&&i===ids.length-1});S.snap=result;for(const k of Object.keys(groups[id])){delete S.pending[k];delete S.authors[k];}}note(submit?'Actividad finalizada. Las diapositivas están disponibles en Mi portafolio.':'Aporte guardado y compartido con tu equipo.');}
function captureRubric(form){const f=new FormData(form),n=k=>f.get(k)===''?null:Number(f.get(k)),individual={};S.snap.members.forEach((m,i)=>{individual[m.id]={order:n(`member_${i}_order`),organization:n(`member_${i}_organization`),contribution:n(`member_${i}_contribution`)};});return {ods_score:n('ods_score'),reasons_score:n('reasons_score'),teamwork_score:n('teamwork_score'),individual_scores:individual,feedback:String(f.get('feedback')||'')};}
function captureResponse(form){const f=new FormData(form),d=content(),questions=d.technique==='entrevista'?[0,1,2,3].filter(i=>d['interview'+i]?.trim()):questionPurposes();return {kind:f.get('kind'),answers:questions.map((_,i)=>d.technique==='entrevista'?{text:String(f.get('text'+i)||'')}:{choice:f.get('answer'+i)===null?null:Number(f.get('answer'+i)),why:String(f.get('why'+i)||'')})};}
async function refresh(){if(portfolio){if((S.odsDraft||window.PortfolioCover?.dirty||window.PortfolioProblem?.dirty||Object.keys(S.pending).length)&&!confirm('¿Actualizar y descartar los cambios sin guardar?'))return;S.pending={};S.authors={};S.odsDraft=null;await loadPortfolio();note('Portafolio actualizado con los trabajos guardados del equipo.');return;}if(Object.keys(S.pending).length&&!confirm('Hay cambios sin guardar. ¿Actualizar y conservar tu borrador para revisarlo sobre los datos más recientes?'))return;S.snap=await rpc('aula_market_snapshot',{p_team:teacher?q.get('equipo'):null});note('Datos actualizados. Tu borrador se conserva; revisa antes de volver a guardarlo.');}
root.addEventListener('input',e=>{if(coverPilot()&&S.mode==='edit'&&window.PortfolioProblem.field(root,e.target))return;if(coverPilot()&&S.mode==='edit'&&window.PortfolioCover.field(root,e.target))return;if(portfolio&&S.mode==='edit'){if(e.target.hasAttribute('data-portfolio-reason')){const d=odsDraft();d.reasons[+e.target.dataset.portfolioReason]=e.target.value;if(coverPilot()){const preview=root.querySelector('[data-pilot-ods-preview]');if(preview){preview.innerHTML=pilotODSFrame(d);window.PortfolioCover.fit(root);}}}if(e.target.hasAttribute('data-portfolio-indicator'))odsDraft().indicator=e.target.value;}if(e.target.dataset.key)patch(e.target.dataset.key,e.target.value);const f=e.target.closest('#market-rubric');if(f)S.rubric=captureRubric(f);const r=e.target.closest('#response-form');if(r)S.responseDraft=captureResponse(r);});
root.addEventListener('change',async e=>{if(coverPilot()&&S.mode==='edit'&&e.target.hasAttribute('data-problem-upload')){const file=e.target.files?.[0],index=+e.target.dataset.problemUpload;if(!file)return;try{S.busy=true;const status=root.querySelector('.problem-upload-status');if(status)status.textContent='Preparando la imagen…';await window.PortfolioProblem.upload(file,index);note('Imagen lista. Guarda los cambios.');}catch(err){window.PortfolioProblem.status(err.message);note(err.message,true);}finally{S.busy=false;render();}return;}if(coverPilot()&&S.mode==='edit'){if(e.target.hasAttribute('data-cover-upload')){const file=e.target.files?.[0];if(!file)return;const editorScroll=root.querySelector('.cover-editor')?.scrollTop||0;try{S.busy=true;window.PortfolioCover.uploadStatus('Preparando la imagen…');const status=root.querySelector('.cover-upload-status');if(status)status.textContent='Preparando la imagen…';await window.PortfolioCover.upload(file);note('Logotipo listo. Ajusta la vista y guarda los cambios.');}catch(err){window.PortfolioCover.uploadStatus(err.message);note(err.message,true);}finally{S.busy=false;render();const editor=root.querySelector('.cover-editor');if(editor)editor.scrollTop=editorScroll;}return;}if(window.PortfolioCover.field(root,e.target))return;}if(portfolio&&S.mode==='edit'&&e.target.hasAttribute('data-portfolio-ods')){odsDraft().ods[+e.target.dataset.portfolioOds]=e.target.value?+e.target.value:null;render();return;}if(portfolio&&S.mode==='edit'&&e.target.hasAttribute('data-portfolio-principal')){odsDraft().principal=+e.target.dataset.portfolioPrincipal;return;}if(e.target.hasAttribute('data-public-target')){patch(e.target.dataset.publicTarget,e.target.value);render();return;}if(e.target.hasAttribute('data-interview-choice')){const i=+e.target.dataset.interviewChoice;if(e.target.value!==''){patch('interview'+i,interviewExamples()[i][+e.target.value]);render();}return;}if(e.target.hasAttribute('data-question-choice')){const i=+e.target.dataset.questionChoice,j=e.target.value;if(j!==''){patch(`q${i}_text`,suggestionSets()[i][0][+j]);render();}return;}const rf=e.target.closest('#market-rubric');if(rf){S.rubric=captureRubric(rf);const r=S.rubric;rf.querySelectorAll('tbody tr').forEach((row,i)=>{const v=r.individual_scores[S.snap.members[i].id],a=[r.ods_score,r.reasons_score,r.teamwork_score,v.order,v.organization,v.contribution];row.lastElementChild.textContent=(a.some(x=>x===null)?'—':a.reduce((n,x)=>n+x,0))+' / 10';});return;}if(e.target.id==='market-actor'){S.actor=e.target.value;render();return;}if(e.target.hasAttribute('data-team')){if(!e.target.value)return;q.set('equipo',e.target.value);window.history.replaceState(null,'',location.pathname+'?'+q);try{S.snap=await rpc('aula_market_snapshot',{p_team:e.target.value});render();}catch(err){note(err.message,true);render();}return;}if(e.target.hasAttribute('data-technique')){if(!enabled())return;if(S.responseDraft&&!confirm('Hay una aplicación sin guardar. ¿Cambiar la técnica y descartar solo ese registro sin guardar?')){render();return;}const old=content().technique;if(old&&old!==e.target.value&&Object.keys(content()).some(k=>/^q[0-7]_text$/.test(k))&&!confirm('Al cambiar de técnica, revisa que las preguntas y opciones sean adecuadas. ¿Continuar?')){render();return;}patch('technique',e.target.value);S.slide=2;S.application=false;S.responseDraft=null;render();return;}if(e.target.hasAttribute('data-image')){if(!enabled())return;const file=e.target.files?.[0];if(!file)return;const actor=S.actor,index=e.target.dataset.image;try{if(!file.type.startsWith('image/')||file.size>12000000)throw Error('Elige una imagen de hasta 12 MB.');S.busy=true;note('Preparando imagen…');render();const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('No se pudo abrir esta imagen. Usa JPG, PNG o WebP.'));img.src=url;});const scale=Math.min(1,640/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const image=canvas.toDataURL('image/jpeg',.78);if(image.length>320000)throw Error('La imagen es muy compleja. Elige una más sencilla.');S.pending[`audience${index}_image`]=image;S.authors[`audience${index}_image`]=actor;note('Imagen lista. Guarda tu aporte.');}finally{URL.revokeObjectURL(url);}}catch(err){note(err.message,true);}finally{S.busy=false;render();}}});
root.addEventListener('click',async e=>{if(coverPilot()&&S.mode==='edit'&&!S.busy){const odsBlock=e.target.closest('[data-pilot-ods-block]');if(odsBlock){pilotODSBlock=+odsBlock.dataset.pilotOdsBlock;render();return;}const problemBlock=e.target.closest('[data-problem-block]');if(problemBlock){window.PortfolioProblem.select(+problemBlock.dataset.problemBlock);render();return;}const problemRemove=e.target.closest('[data-problem-remove]');if(problemRemove){window.PortfolioProblem.remove(+problemRemove.dataset.problemRemove);render();return;}const tab=e.target.closest('[data-cover-tab]');if(tab){window.PortfolioCover.tab(tab.dataset.coverTab);render();return;}const palette=e.target.closest('[data-cover-palette]');if(palette){window.PortfolioCover.palette(+palette.dataset.coverPalette);render();return;}if(e.target.closest('[data-cover-reset]')){window.PortfolioCover.reset();render();return;}if(e.target.closest('[data-cover-remove]')){window.PortfolioCover.remove();render();return;}}const b=e.target.closest('[data-market]');if(!b||b.disabled||S.busy)return;const action=b.dataset.market;try{S.error=false;if(action==='portfolio-edit'){if(!portfolioCanEdit())return;S.mode='edit';if(S.slide===-2)window.PortfolioCover.begin();if(S.slide===-3)window.PortfolioProblem.begin();render();return;}if(action==='portfolio-cancel'){if(coverPilot()){window.PortfolioCover.cancel();window.PortfolioProblem.cancel();}S.pending={};S.authors={};S.odsDraft=null;S.mode='presentacion';render();return;}if(action==='portfolio-save'){S.busy=true;render();try{await savePortfolioChanges();}finally{S.busy=false;}render();return;}if(action==='slide'){if(portfolio&&S.mode==='edit'){S.busy=true;try{await savePortfolioChanges();}finally{S.busy=false;}}S.slide=slides().includes(+b.dataset.index)?+b.dataset.index:0;render();return;}if(action==='mode'){if(portfolio)return;if(S.mode==='edit'&&Object.keys(S.pending).length)await save();S.mode=S.mode==='presentacion'?'edit':'presentacion';S.application=false;S.notice='';render();return;}if(action==='remove-image'){patch(`audience${b.dataset.index}_image`,'');render();return;}if(action==='analysis'){const group=surveyGroups().find(g=>g.id===b.dataset.group);if(group){patch('analysis_'+group.id,analysisSuggestion(group));render();}return;}if(action==='suggestions'){if(!surveyOnly()&&!content().technique)throw Error('Marca primero la técnica principal.');if(Object.keys(content()).some(k=>/^q[0-7]_(text|a|b|c)$/.test(k))&&!confirm('¿Reemplazar las preguntas y opciones actuales por sugerencias editables? Las aplicaciones anteriores conservan su instrumento.'))return;for(const [k,v]of Object.entries(suggestions()))patch(k,v);note('Sugerencias preparadas. Los precios son ejemplos: ajusten sus rangos al producto. Ajusten las preguntas y opciones a su público y revisen los precios antes de aplicar.');render();return;}if(action==='toggle-application'){if(!S.application){if(Object.keys(S.pending).length)await save();S.application=true;}else S.application=false;render();return;}if(action==='print'){window.print();return;}if(action==='full'){if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.classList.contains('portfolio-projector'))document.documentElement.classList.remove('portfolio-projector');else{try{await document.documentElement.requestFullscreen();}catch(err){if(coverPilot())document.documentElement.classList.add('portfolio-projector');else throw err;}}return;}S.busy=true;render();if(action==='save'||action==='submit'){// save() checks the publication and contributor; busy only prevents duplicate UI operations.
 await save(action==='submit');
 }else if(action==='refresh')await refresh();}catch(err){note(err.message,true);}finally{S.busy=false;render();}});
root.addEventListener('submit',async e=>{e.preventDefault();if(S.busy)return;const id=e.target.id;if(id==='market-rubric'){S.rubric=captureRubric(e.target);const r=S.rubric;S.busy=true;render();try{await rpc('aula_teacher_save_evaluation',{p_team:S.snap.team.id,p_publication:S.snap.publication.id,p_values:{ods:r.ods_score,reasons:r.reasons_score,teamwork:r.teamwork_score,members:r.individual_scores,comment:r.feedback}});S.snap=await rpc('aula_market_snapshot',{p_team:S.snap.team.id});S.rubric=null;note('Evaluación guardada: una sola nota de 7 puntos grupales y 3 individuales.');}catch(err){note(err.message,true);}finally{S.busy=false;render();}}else if(id==='response-form'){S.responseDraft=captureResponse(e.target);const d=S.responseDraft;S.busy=true;render();try{if(!S.actor)throw Error('Selecciona quién registra esta aplicación.');S.snap=await rpc('aula_market_add_response',{p_member:S.actor,p_answers:d.answers,p_kind:d.kind,p_expected:S.snap.work.version});S.responseDraft=null;S.application=false;note('Aplicación guardada. Se conserva como '+(d.kind==='real'?'registro real.':'ensayo de práctica.'));}catch(err){note(err.message,true);}finally{S.busy=false;render();}}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.documentElement.classList.remove('portfolio-projector');});
window.addEventListener('beforeunload',e=>{if(Object.keys(S.pending).length||S.odsDraft||S.rubric||S.responseDraft){e.preventDefault();e.returnValue='';}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.documentElement.classList.remove('portfolio-projector');});
window.addEventListener('beforeunload',e=>{if(portfolio&&(window.PortfolioCover?.dirty||window.PortfolioProblem?.dirty)){e.preventDefault();e.returnValue='';}});
window.MarketUI={state:S,coverPilot,hasMarket,hasODS,slide,suggestions,render,surveyGroups,resultPages,analysisSuggestion,slides};
window.MarketReady=(async()=>{render();try{client=window.supabase.createClient(config.url,config.publishableKey,{auth:{storageKey:teacher?'ea-aula-supabase-session-v1':'ea-aula-student-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:false}});const {data,error}=await client.auth.getSession();if(error||!data.session)throw Error(teacher?'Ingresa primero desde el panel docente.':'Ingresa primero a Mi aula con tu nombre y equipo.');if(portfolio)await loadPortfolio();else S.snap=await rpc('aula_market_snapshot',{p_team:teacher?q.get('equipo'):null});if(teacher&&!S.snap.teacher)throw Error('Acceso exclusivo docente.');}catch(err){S.snap=null;note(err.message,true);}render();})();
})();
